function detectOrg(text){
  if(/動画|youtube|tiktok|リール|映像/i.test(text)) return 'video';
  if(/育児|子育て|献立|家事|保育/.test(text)) return 'family';
  if(/投稿|インスタ|instagram|threads|スレッズ|発信|SNS/i.test(text)) return 'sns';
  if(/ショップ|通販|BOOTH|出品|商品説明|ネット販売/i.test(text)) return 'shop';
  if(/ブログ|記事|note|コラム|メディア/i.test(text)) return 'writing';
  if(/データ|集計|分析|レポート|グラフ|売上/.test(text)) return 'data';
  if(/見積|請求|メール|議事録|経理|事務|書類|日報|経費|営業|効率/.test(text)) return 'work';
  if(/ニュース|調べ|リサーチ|要約|収集|まとめ/.test(text)) return 'research';
  if(/アプリ|ツール|家計簿|CRM|システム|サイト|管理|予約|在庫/.test(text)) return 'dev';
  return 'general';
}

