async function walkX(i, tx, token){
  const a=agents[i]; a.el.classList.add('walk');
  while(a.x !== tx){
    if(token!==RUN) return false;
    const s = Math.sign(tx-a.x)*Math.min(TILE, Math.abs(tx-a.x)); a.x+=s;
    a.el.classList.toggle('right', s>0); a.el.classList.toggle('left', s<0); a.el.classList.remove('up');
    a.el.style.left=a.x+'px'; await wait(210);
  }
  a.el.classList.remove('walk','right','left'); return true;
}

async function walkY(i, ty, token){
  const a=agents[i]; a.el.classList.add('walk');
  while(a.y !== ty){
    if(token!==RUN) return false;
    const s = Math.sign(ty-a.y)*Math.min(TILE, Math.abs(ty-a.y)); a.y+=s;
    a.el.classList.toggle('up', s<0); a.el.classList.remove('right','left');
    a.el.style.top=a.y+'px'; await wait(210);
  }
  a.el.classList.remove('walk','up'); return true;
}

async function go(i, spot, token){
  const a=agents[i];
  if(a.y !== CORRIDOR && !(await walkY(i, CORRIDOR, token))) return false;
  if(a.x !== spot.x && !(await walkX(i, spot.x, token))) return false;
  if(spot.y !== CORRIDOR && !(await walkY(i, spot.y, token))) return false;
  return true;
}

async function say(i, text, token, ms=1300){
  const b=document.getElementById('bub'+i); if(!b) return;
  b.textContent=text; agents[i].el.classList.add('say');
  await wait(ms); if(token===RUN) agents[i].el.classList.remove('say');
}

async function tick(to, token){
  const from=mins, steps=12;
  for(let s=1;s<=steps;s++){
    if(token!==RUN) return;
    mins = Math.round(from + (to-from)*s/steps);
    document.getElementById('clock').textContent =
      String(Math.floor(mins/60)).padStart(2,'0')+':'+String(mins%60).padStart(2,'0');
    document.getElementById('clockbar').style.width = ((mins-540)/540*100)+'%';
    await wait(70);
  }
}

async function playDay(org, goalText, token){
  while(token===RUN){
    mins=540;
    document.getElementById('clock').textContent='09:00';
    document.getElementById('clockbar').style.width='0%';
    document.querySelectorAll('#missions li').forEach(li=>li.classList.remove('done'));
    document.getElementById('mcount').textContent='0/'+org.missions.length;
    let doneN=0;
    for(let s=0;s<org.flow.length;s++){
      if(token!==RUN) return;
      const [ai, spot, line, doneText, effect] = org.flow[s];
      const a = org.agents[ai];
      setChip(ai,'出発！');
      if(spot==='studio') document.getElementById('onair').classList.add('on');
      if(spot){ if(!(await go(ai, SPOTS[spot], token))) return; }
      if(token!==RUN) return;
      await say(ai, line, token, 1400);
      document.getElementById('onair').classList.remove('on');
      const li=document.querySelectorAll('#missions li')[s];
      if(li) li.classList.add('done');
      doneN++; document.getElementById('mcount').textContent=doneN+'/'+org.missions.length;
      dialog(doneText.replaceAll('{goal}', goalText || 'つくりたいもの'));
      if(effect) effect();
      setChip(ai, org.agents[ai].task);
      if(spot){ if(!(await go(ai, agents[ai].home, token))) return; }
      await tick(TIMES[s], token);
    }
    if(token!==RUN) return;
    dialog('きょうの ミッションは 全部できた！ おつかれさま！'); await wait(3200);
  }
}
